def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:  # Background value
                preserved = 1

                # Check if there's a preserved value on left (in the same row)
                has_left = False
                for col in range(c-1, -1, -1):
                    if grid[r][col] == preserved:
                        has_left = True
                        break
                    if grid[r][col] != 0:
                        break

                # Check if there's a preserved value on right (in the same row)
                has_right = False
                for col in range(c+1, cols):
                    if grid[r][col] == preserved:
                        has_right = True
                        break
                    if grid[r][col] != 0:
                        break

                # Check if there's a preserved value up (in the same column)
                has_up = False
                for row in range(r-1, -1, -1):
                    if grid[row][c] == preserved:
                        has_up = True
                        break
                    if grid[row][c] != 0:
                        break

                # Check if there's a preserved value down (in the same column)
                has_down = False
                for row in range(r+1, rows):
